//! The pack that ships with the app ("Open20 Essentials", generated by
//! `scripts/builtin-pack/build.py`). It's installed like any other pack — so
//! it can be turned off or uninstalled from the Assets window — on the first
//! start, and again only when the app brings a new version of it: an
//! uninstall sticks until then, and a reinstall keeps it on or off as it was.

use std::fs;
use std::io::Cursor;

use tauri::AppHandle;

use super::format::{read_index, read_manifest};
use super::install::install_from;
use super::registry::{packs_root, read_registry};
use super::{PackError, Result};

/// The pack's file among the app's bundled resources (see build.rs and the
/// `bundle.resources` of tauri.conf.json).
const RESOURCE: &str = "builtin.dungeondraft_pack";

/// Version of the bundled pack, read by build.rs from its manifest; empty when
/// the app was built without the pack.
const VERSION: &str = env!("BUILTIN_PACK_VERSION");

/// Records which version of the built-in pack was last installed.
const MARKER: &str = "builtin.version";

/// The pack's bytes from the bundled resources. On Android they live in the
/// APK's assets, which aren't files: they're read through the AssetManager.
fn read_resource(app: &AppHandle) -> Result<Vec<u8>> {
    #[cfg(target_os = "android")]
    {
        let _ = app;
        crate::android_fs::read_asset(RESOURCE).map_err(PackError::Other)
    }
    #[cfg(not(target_os = "android"))]
    {
        use tauri::path::BaseDirectory;
        use tauri::Manager;
        let path = app
            .path()
            .resolve(RESOURCE, BaseDirectory::Resource)
            .map_err(|e| PackError::Other(e.to_string()))?;
        Ok(fs::read(path)?)
    }
}

/// A pack's id and version, from its manifest.
fn manifest_id_version(pack: &[u8]) -> Result<(String, String)> {
    let mut reader = Cursor::new(pack);
    let entries = read_index(&mut reader)?;
    let m = read_manifest(&mut reader, &entries)?;
    Ok((m.id.unwrap_or_default(), m.version.unwrap_or_default()))
}

/// Whether the bundled version needs installing, given the last one installed.
fn needs_install(installed: Option<&str>, bundled: &str) -> bool {
    installed.map(str::trim) != Some(bundled)
}

/// Install the built-in pack if this version of it hasn't been yet. The
/// resource (tens of MB) is only read when it has to be installed.
pub(crate) fn ensure_installed(app: &AppHandle) -> Result<()> {
    if VERSION.is_empty() {
        return Ok(());
    }
    let marker = packs_root(app)?.join(MARKER);
    let last = fs::read_to_string(&marker).ok();
    if !needs_install(last.as_deref(), VERSION) {
        return Ok(());
    }
    let pack = read_resource(app)?;
    let (id, version) = manifest_id_version(&pack)?;
    let enabled = read_registry(app).get(&id).map(|r| r.enabled);
    install_from(app, &mut Cursor::new(&pack), enabled)?;
    fs::write(marker, version)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The pack build.rs wrote for this build (empty without resources/builtin/).
    fn packed() -> Vec<u8> {
        fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/resources/",
            "builtin.dungeondraft_pack"
        ))
        .unwrap_or_default()
    }

    #[test]
    fn bundled_pack_has_a_manifest() {
        let pack = packed();
        if pack.is_empty() {
            return; // built without resources/builtin/ (see build.rs)
        }
        let (id, version) = manifest_id_version(&pack).expect("readable pack");
        assert_eq!(id, "open20-essentials");
        assert_eq!(version, VERSION);
    }

    #[test]
    fn bundled_pack_ships_every_category() {
        let pack = packed();
        if pack.is_empty() {
            return; // built without resources/builtin/ (see build.rs)
        }
        let entries = read_index(&mut Cursor::new(&pack)).expect("index");
        for cat in [
            "tilesets",
            "walls",
            "portals",
            "caves",
            "roofs",
            "paths",
            "objects",
            "terrain",
            "lights",
            "materials",
        ] {
            let prefix = format!("res://packs/open20-essentials/textures/{cat}/");
            assert!(
                entries.iter().any(|e| e.path.starts_with(&prefix)),
                "missing {cat}"
            );
        }
        // Every entry lies inside the pack data.
        let len = pack.len() as u64;
        assert!(entries.iter().all(|e| e.offset + e.size <= len));
    }

    #[test]
    fn installs_only_new_versions() {
        assert!(needs_install(None, "1.0.0"));
        assert!(needs_install(Some("0.9.0"), "1.0.0"));
        assert!(!needs_install(Some("1.0.0\n"), "1.0.0"));
    }
}
